  seq integer not null unique,
  ts timestamptz not null default now(),
  actor_person_id text,
  actor_role text,
  action text not null,
  entity_table text,
  entity_id text,
  outcome text not null default 'ok' check (outcome in ('ok', 'refused', 'error')),
  reason text,
  before_hash text,
  after_hash text,
  request_id text,
  prev_hash text not null,
  hash text not null,
  ledger_status text not null default 'not_applicable' check (ledger_status in ('written', 'skipped', 'not_applicable')),
  ledger_seq integer
);
comment on table kafaa_audit_events is '[M16] Append-only, hash-chained audit log';

