-- M08 · Employee Concerns Program channels (content owned by ECP)
create table if not exists kafaa_ecp_channels (
  id text primary key,
  kind text not null,
  label_en text not null,
  label_ar text not null,
  detail_en text not null,
  detail_ar text not null,
  sort integer not null default 0,
  source text not null
);
comment on table kafaa_ecp_channels is '[M08] Employee Concerns Program channels (content owned by ECP)';

-- M08 · [K] ECP referral log: metadata only, never the concern text; anonymous option
create table if not exists kafaa_concern_cases (
  id text primary key,
  ref_no text not null unique,
  received_on date not null,
  channel text not null check (channel in ('ecp_office', 'intranet', 'phone', 'email', 'unit_rep', 'r2p_referral')),
