  status text not null default 'received' check (status in ('received', 'triaged', 'investigating', 'referred', 'closed')),
  priority text not null default 'routine' check (priority in ('routine', 'priority', 'urgent')),
  triage_owner_role text,
  triaged_at timestamptz,
  ecp_system_ref text not null,
  sample boolean not null default true
);
comment on table kafaa_concern_cases is '[M08] [K] ECP referral log: metadata only, never the concern text; anonymous option';

-- M11 · Technology family evaluated under ADVANCE (no deployment decision implied)
create table if not exists kafaa_adv_technologies (
  id text primary key,
  family_en text not null,
  family_ar text not null,
  partners_en text not null,
  partners_ar text not null,
  designs text not null,
  skill_areas_en text not null,
  skill_areas_ar text not null,
  mou_date text not null,
