  sort integer not null default 0
);
comment on table kafaa_adv_technologies is '[M11] Technology family evaluated under ADVANCE (no deployment decision implied)';

-- M11 · What transfers from a current role to a future technology, and what is new
create table if not exists kafaa_skill_bridges (
