  from_role_id text not null,
  tech_id text not null,
  transfers_en text not null,
  transfers_ar text not null,
  new_en text not null,
  new_ar text not null
);
comment on table kafaa_skill_bridges is '[M11] What transfers from a current role to a future technology, and what is new';

-- M11 · Future-skills radar values (SIMULATED scenarios, never forecasts)
create table if not exists kafaa_future_skills (
  id text primary key,
  skill_en text not null,
  skill_ar text not null,
  tech_ids text[] not null default '{}'::text[],
  scenario text not null,
  value numeric not null,
  simulated boolean not null default true
);
comment on table kafaa_future_skills is '[M11] Future-skills radar values (SIMULATED scenarios, never forecasts)';

-- M16 · Content page with sources, review date and bilingual approval
create table if not exists kafaa_content_pages (
  id text primary key,
  slug text not null unique,
  zone text not null check (zone in ('public', 'staff', 'partner')),
  module text not null,
  title_en text not null,
  title_ar text not null,
  body_en text not null,
  body_ar text not null,
  sources jsonb not null default '[]'::jsonb,
  as_of date not null,
  review_on date not null,
  status text not null default 'draft' check (status in ('draft', 'in_translation', 'in_review', 'published')),
  is_published boolean not null default false,
  translation_status text not null default 'en_only' check (translation_status in ('en_only', 'ar_draft', 'both_approved')),
  owner_role text not null default 'Editor',
  ecp_owned boolean not null default false
);
comment on table kafaa_content_pages is '[M16] Content page with sources, review date and bilingual approval';

-- M12 · Sourced statistic with "as of" date (or SAMPLE label)
create table if not exists kafaa_facts (
  id text primary key,
  key text not null unique,
  label_en text not null,
  label_ar text not null,
  value text not null,
  value_ar text not null default '',
  detail_en text not null default '',
  detail_ar text not null default '',
  source_id text,
  as_of date not null,
  sample boolean not null default false,
  public boolean not null default true,
  conflict_note text,
  topic text not null default 'barakah'
);
comment on table kafaa_facts is '[M12] Sourced statistic with "as of" date (or SAMPLE label)';

