  term_en text not null,
  term_ar text not null,
  definition_en text not null,
  definition_ar text not null,
  owner text not null default 'Nuclear Training',
  status text not null default 'draft' check (status in ('draft', 'reviewed'))
);
comment on table kafaa_glossary is '[M15] Arabic-English nuclear glossary (owner: Nuclear Training)';

-- M12 · FAQ
create table if not exists kafaa_faqs (
  id text primary key,
  topic text not null,
  q_en text not null,
  q_ar text not null,
  a_en text not null,
  a_ar text not null,
  sort integer not null default 0
);
comment on table kafaa_faqs is '[M12] FAQ';

-- M13 · Approved corpus document for Dalil grounding
create table if not exists kafaa_corpus_docs (
  id text primary key,
  title text not null,
  url text,
  kind text not null check (kind in ('kafaa_page', 'enec_page', 'fanr_page', 'internal')),
