  updated_at timestamptz not null default now()
);
comment on table kafaa_corpus_docs is '[M13] Approved corpus document for Dalil grounding';

-- M13 · Dalil session (retained for a limited period)
create table if not exists kafaa_advisor_sessions (
  id text primary key,
  person_id text,
  mode text not null check (mode in ('public', 'applicant', 'staff', 'partner')),
  started_at timestamptz not null default now(),
  retention_until date not null,
  handoff text not null default 'none' check (handoff in ('none', 'careers', 'training', 'partner_desk')),
  handoff_consent boolean not null default false,
  turns integer not null default 0
);
comment on table kafaa_advisor_sessions is '[M13] Dalil session (retained for a limited period)';

-- M13 · Dalil turn (question, cited answer or refusal)
create table if not exists kafaa_advisor_turns (
  id text primary key,
  session_id text not null,
  person_id text,
  speaker text not null check (speaker in ('user', 'dalil')),
  text text not null,
  citations jsonb not null default '[]'::jsonb,
  refused boolean not null default false,
  refusal_category text,
  ts timestamptz not null default now()
);
comment on table kafaa_advisor_turns is '[M13] Dalil turn (question, cited answer or refusal)';

-- M13 · Dalil evaluation run (citation and refusal thresholds)
create table if not exists kafaa_eval_runs (
  id text primary key,
  run_at timestamptz not null,
  release text not null,
  lang text not null check (lang in ('en', 'ar', 'both')),
  in_scope_total integer not null,
  cited_correct integer not null,
  refusal_total integer not null,
  refusal_correct integer not null,
  pass boolean not null,
  notes text not null default ''
);
comment on table kafaa_eval_runs is '[M13] Dalil evaluation run (citation and refusal thresholds)';

-- M13 · Dalil refusal policy per out-of-scope category
create table if not exists kafaa_refusal_policies (
  id text primary key,
  category text not null,
  description_en text not null,
  description_ar text not null,
  patterns text[] not null default '{}'::text[],
  response_en text not null,
  response_ar text not null,
  enabled boolean not null default true,
  stop_conversation boolean not null default false
);
comment on table kafaa_refusal_policies is '[M13] Dalil refusal policy per out-of-scope category';

-- M13 · Dalil global settings and kill switch
create table if not exists kafaa_dalil_settings (
  id text primary key,
  enabled boolean not null default true,
  public_rate_limit_per_hour integer not null default 20,
  staff_mode boolean not null default false,
  model_gateway text not null default 'UAE-hosted model option (concept)',
  retention_days integer not null default 30,
  updated_at timestamptz not null default now(),
  updated_by text
);
comment on table kafaa_dalil_settings is '[M13] Dalil global settings and kill switch';

-- M16 · Connector and sync status (systems of record)
create table if not exists kafaa_integrations (
  id text primary key,
  name text not null,
  system_kind text not null,
  domain text not null,
  direction text not null check (direction in ('in', 'out', 'both')),
  last_success timestamptz not null,
  threshold_hours integer not null default 24,
  status text not null check (status in ('ok', 'degraded', 'stale', 'error', 'disabled')),
  records integer not null default 0,
  errors integer not null default 0,
  schedule text not null default '',
  notes text not null default ''
);
comment on table kafaa_integrations is '[M16] Connector and sync status (systems of record)';

